103	  const lv_image_dsc_t *base;      /* IDLE / WAITING open-eye frame */
104	  const lv_image_dsc_t *blink;     /* WAITING closed-eye frame */
105	  const lv_image_dsc_t *eyes_up;   /* THINKING */
106	  const lv_image_dsc_t *eyes_down; /* LISTENING */
107	  const lv_image_dsc_t *focused;   /* EXECUTING */
108	  const lv_image_dsc_t *error;     /* ERROR */
109	};
