65	struct standby_state_s {
66	  bool initialized;
67	  bool visible;
68	  lv_obj_t *screen;
69	  lv_obj_t *content; /* 居中一列(clock/date/hint),淡入只作用于它 */
70	  lv_obj_t *clock;   /* HH:MM — Montserrat 24 */
71	  lv_obj_t *date;    /* M月D日 周X — MiSans 16 CJK */
72	  lv_obj_t *hint;    /* 待机中 — MiSans 16 CJK */
73	  lv_obj_t *prev_screen;
