77	static struct standby_state_s s_sb;
78	
79	static void refresh_time(void)
80	{
81	  if (!s_sb.initialized) return;
82	
83	  time_t now = time(NULL);
84	  struct tm tm;
85	  localtime_r(&now, &tm);
86	
87	  if (s_sb.clock)
88	    {
89	      char buf[16];
90	      snprintf(buf, sizeof(buf), "%02d:%02d", tm.tm_hour, tm.tm_min);
91	      lv_label_set_text(s_sb.clock, buf);
92	    }
93	  if (s_sb.date)
94	    {
95	      char buf[32];
96	      snprintf(buf, sizeof(buf), "%d月%d日 %s",
97	               tm.tm_mon + 1, tm.tm_mday, s_wday_cn[tm.tm_wday % 7]);
98	      lv_label_set_text(s_sb.date, buf);
99	    }
100	}
