109	/* ---------- screen show / hide (async, runs in LVGL thread) ---------- */
110	
111	static void show_async_cb(void *data)
112	{
113	  (void)data;
114	  if (!s_sb.initialized || !s_sb.screen || s_sb.visible) return;
115	  s_sb.prev_screen = lv_screen_active();
116	  refresh_time();
117	
118	  /* 背景与上一屏同为不透明 UI_PAL_BG,直接换屏瞬时可见性无差;只对内容层做
119	   * opacity 淡入(脏区 = 内容包围盒,而非整屏),淡入不再受整帧 SPI flush 限制。
120	   * 先手动把内容层压到全透明,避免换屏后首帧闪一下。 */
121	  if (s_sb.content)
122	    {
123	      lv_obj_set_style_opa(s_sb.content, LV_OPA_TRANSP, 0);
124	      lv_screen_load(s_sb.screen);
125	      lv_obj_fade_in(s_sb.content, SCREEN_FADE_MS, 0);
126	    }
127	  else
128	    {
129	      lv_screen_load(s_sb.screen);
130	    }
131	
132	  s_sb.visible = true;
133	  syslog(LOG_INFO, "[%s] standby clock shown\n", TAG);
134	}
135	
136	void standby_view_show(void)
137	{
138	  if (!s_sb.initialized) return;
139	  lv_async_call(show_async_cb, NULL);
140	}
141	
142	static void hide_async_cb(void *data)
143	{
144	  (void)data;
145	  if (!s_sb.initialized || !s_sb.visible) return;
146	  /* 唤醒应即时:直接切回上一屏(其内容一直是全不透明,无需淡入)。背景同色,
147	   * 瞬时切换无视觉跳变。 */
148	  if (s_sb.prev_screen)
149	    lv_screen_load(s_sb.prev_screen);
150	  s_sb.visible = false;
151	  syslog(LOG_INFO, "[%s] standby clock hidden\n", TAG);
152	}
153	
154	void standby_view_hide(void)
155	{
156	  if (!s_sb.initialized) return;
157	  lv_async_call(hide_async_cb, NULL);
158	}
