188	                        LV_FLEX_ALIGN_CENTER);
189	  lv_obj_set_style_pad_row(col, 14, 0);
190	  lv_obj_center(col);
191	
192	  s_sb.content = col;
193	
194	  s_sb.clock = lv_label_create(col);
195	  if (!s_sb.clock) goto fail;
196	  lv_label_set_text(s_sb.clock, "--:--");
197	  lv_obj_set_style_text_font(s_sb.clock, &lv_font_montserrat_24, 0);
198	  lv_obj_set_style_text_color(s_sb.clock, lv_color_hex(UI_PAL_IDLE), 0);
199	
200	  s_sb.date = lv_label_create(col);
201	  if (!s_sb.date) goto fail;
202	  lv_label_set_text(s_sb.date, "待机中");
203	  lv_obj_set_style_text_font(s_sb.date, &lv_font_misans_16_cjk, 0);
204	  lv_obj_set_style_text_color(s_sb.date, lv_color_hex(UI_PAL_MUTED), 0);
205	
206	  s_sb.hint = lv_label_create(col);
207	  if (!s_sb.hint) goto fail;
208	  lv_label_set_text(s_sb.hint, "待机中");
209	  lv_obj_set_style_text_font(s_sb.hint, &lv_font_misans_16_cjk, 0);
210	  lv_obj_set_style_text_color(s_sb.hint, lv_color_hex(UI_PAL_MUTED), 0);
211	
212	  s_sb.timer = lv_timer_create(timer_cb, 1000, NULL);
213	  if (s_sb.timer)
214	    lv_timer_set_repeat_count(s_sb.timer, -1);
215	
216	  s_sb.initialized = true;
217	  syslog(LOG_INFO, "[%s] init OK (暗色数字时钟)\n", TAG);
218	  return 0;
219	
220	fail:
221	  if (s_sb.screen) lv_obj_del(s_sb.screen);
222	  memset(&s_sb, 0, sizeof(s_sb));
