115	/* Per-type expression frame tables.  All six faces share the same state→face
116	 * mapping (base/blink/eyes_up/eyes_down/focused/error); the pet type only
117	 * swaps which sprite sheet supplies those faces. */
118	struct pet_frames_s {
119	  const lv_image_dsc_t *base;      /* IDLE / WAITING open-eye frame */
120	  const lv_image_dsc_t *blink;     /* WAITING closed-eye frame */
121	  const lv_image_dsc_t *eyes_up;   /* THINKING */
122	  const lv_image_dsc_t *eyes_down; /* LISTENING */
123	  const lv_image_dsc_t *focused;   /* EXECUTING */
124	  const lv_image_dsc_t *error;     /* ERROR */
125	};
