150	static const struct pet_frames_s *s_frames = &s_frames_by_type[PET_TYPE_CAT];
151	
152	/* ---------- animation exec callbacks (LVGL v9: (obj, value)) ---------- */
153	
154	/* LVGL v9 exec_cb signature is lv_anim_exec_xcb_t = void(*)(void*, lv_anim_value_t),
155	 * i.e. the first arg is the animated var (void*), NOT lv_obj_t* nor lv_anim_t*.
156	 * We cast to lv_obj_t* inside for the lv_obj and lv_arc calls. */
157	/* Spinner: a 90° segment rotating (THINKING / LISTENING). value = start angle. */
158	static void spin_cb(void *obj, int32_t v)
159	{
160	  lv_obj_t *o = (lv_obj_t *)obj;
161	  lv_arc_set_angles(o, v, v + 90);
162	}
163	
164	/* Growing fill: indicator grows 0→360 (EXECUTING). value = end angle. */
165	static void fill_cb(void *obj, int32_t v)
166	{
167	  lv_obj_t *o = (lv_obj_t *)obj;
168	  lv_arc_set_angles(o, 0, v);
169	}
170	
171	/* Breathing: sprite opacity pulses (IDLE). value 0..100. */
172	static void breathe_cb(void *obj, int32_t v)
173	{
174	  lv_obj_t *o = (lv_obj_t *)obj;
175	  /* 100% → 255, 0% → 190 (gentle). */
176	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
177	}
178	
179	/* Float: gentle vertical bob (IDLE, layered with the opacity breathe so the
180	 * idle pet feels alive rather than a static icon). value 0..100. */
181	static void float_cb(void *obj, int32_t v)
182	{
183	  lv_obj_t *o = (lv_obj_t *)obj;
184	  /* Triangle 0→+2→0→-2→0 across one cycle — a ±2px bob on a 96px sprite. */
185	  int32_t amp;
186	  if (v < 25)      amp = (v * 2) / 25;
187	  else if (v < 50) amp = ((50 - v) * 2) / 25;
188	  else if (v < 75) amp = -((v - 50) * 2) / 25;
189	  else             amp = -((100 - v) * 2) / 25;
190	  lv_obj_set_style_translate_y(o, amp, 0);
191	}
192	
193	/* Blink: swap between open/closed eyes (WAITING). value 0..100, closed at mid. */
194	static void blink_cb(void *obj, int32_t v)
195	{
196	  lv_obj_t *o = (lv_obj_t *)obj;
197	  /* open → closed(35..65) → open.  Two-frame swap reads as a pixel blink. */
198	  lv_image_set_src(o, (v >= 35 && v <= 65) ? s_frames->blink
199	                                            : s_frames->base);
200	}
201	
202	/* Shake: sprite x jitter (ERROR). value 0..100 maps to a few oscillations. */
203	static void shake_cb(void *obj, int32_t v)
204	{
205	  lv_obj_t *o = (lv_obj_t *)obj;
206	  /* 0..100 → four half-swings of ±5px. Simple triangle per 25-step. */
207	  int seg = v / 25;
208	  int phase = v % 25;
209	  int amp = (phase < 13) ? (phase * 5 / 12) : ((25 - phase) * 5 / 12);
210	  int sign = (seg % 2 == 0) ? 1 : -1;
211	  lv_obj_set_style_translate_x(o, sign * amp, 0);
212	}
213	
214	static void stop_anim(void)
215	{
216	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
217	  if (s_pet.ring)   lv_anim_delete(s_pet.ring,   spin_cb);
218	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, breathe_cb);
219	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, shake_cb);
220	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, blink_cb);
221	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, float_cb);
222	  s_pet.anim_active = false;
223	}
224	
225	/* Per-state face: each agent state shows a distinct expression (eyes-only edits
226	 * on the CC0 base face — see gen_pet_expressions.py).  WAITING returns the
227	 * open-eye base because its blink anim swaps base↔blink itself. */
228	static const lv_image_dsc_t *sprite_for(enum pet_state st)
229	{
230	  switch (st)
231	    {
232	      case PET_STATE_LISTENING: return s_frames->eyes_down;
233	      case PET_STATE_THINKING:  return s_frames->eyes_up;
234	      case PET_STATE_EXECUTING: return s_frames->focused;
235	      case PET_STATE_ERROR:     return s_frames->error;
236	      case PET_STATE_WAITING:
237	      case PET_STATE_IDLE:
238	      default:                  return s_frames->base;
239	    }
240	}
241	
242	static void start_anim_for(enum pet_state st)
243	{
244	  lv_anim_t a;
245	  uint32_t color = s_state_color[st];
246	
247	  stop_anim();
248	  if (!s_pet.ring || !s_pet.sprite) return;
249	
250	  /* Indicator color always tracks state (the dark track stays constant);
251	   * base angles reset per effect. */
252	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), LV_PART_INDICATOR);
253	
254	  /* Face tracks state too — each state's expression frame (blink anim swaps it). */
255	  lv_image_set_src(s_pet.sprite, sprite_for(st));
256	
257	  switch (st)
258	    {
259	      case PET_STATE_THINKING:
260	      case PET_STATE_LISTENING:
261	        lv_anim_init(&a);
262	        lv_anim_set_var(&a, s_pet.ring);
263	        lv_anim_set_values(&a, 0, 360);
264	        lv_anim_set_time(&a, 1400);
265	        lv_anim_set_exec_cb(&a, spin_cb);
266	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
267	        lv_anim_start(&a);
268	        break;
269	      case PET_STATE_EXECUTING:
270	        lv_anim_init(&a);
271	        lv_anim_set_var(&a, s_pet.ring);
272	        lv_anim_set_values(&a, 0, 360);
273	        lv_anim_set_time(&a, 900);
274	        lv_anim_set_exec_cb(&a, fill_cb);
275	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
276	        lv_anim_start(&a);
277	        break;
278	      case PET_STATE_IDLE:
279	        lv_anim_init(&a);
280	        lv_anim_set_var(&a, s_pet.sprite);
281	        lv_anim_set_values(&a, 0, 100);
282	        lv_anim_set_time(&a, 1800);
283	        lv_anim_set_exec_cb(&a, breathe_cb);
284	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
285	        lv_anim_start(&a);
286	        /* Layered float: a slow bob on a distinct period so the two effects
287	         * don't phase-lock.  lv_anim_start copies `a`, so it is safe to reuse
288	         * the same local descriptor for a second anim. */
289	        lv_anim_init(&a);
290	        lv_anim_set_var(&a, s_pet.sprite);
291	        lv_anim_set_values(&a, 0, 100);
292	        lv_anim_set_time(&a, 2600);
293	        lv_anim_set_exec_cb(&a, float_cb);
294	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
295	        lv_anim_start(&a);
296	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
297	        break;
298	      case PET_STATE_WAITING:
299	        lv_anim_init(&a);
300	        lv_anim_set_var(&a, s_pet.sprite);
301	        lv_anim_set_values(&a, 0, 100);
302	        lv_anim_set_time(&a, 900);
303	        lv_anim_set_exec_cb(&a, blink_cb);
304	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
305	        lv_anim_start(&a);
306	        lv_arc_set_angles(s_pet.ring, 0, 360);
307	        break;
308	      case PET_STATE_ERROR:
309	        lv_anim_init(&a);
310	        lv_anim_set_var(&a, s_pet.sprite);
311	        lv_anim_set_values(&a, 0, 100);
312	        lv_anim_set_time(&a, 350);
313	        lv_anim_set_exec_cb(&a, shake_cb);
314	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
315	        lv_anim_start(&a);
316	        lv_arc_set_angles(s_pet.ring, 0, 360);
317	        break;
318	      default:
319	        lv_arc_set_angles(s_pet.ring, 0, 360);
320	        break;
321	    }
322	  s_pet.anim_active = true;
323	}
324	
325	/* ---------- async apply (runs in LVGL thread) ---------- */
326	
327	static void apply_state_async_cb(void *data)
328	{
329	  enum pet_state st = (enum pet_state)(intptr_t)data;
330	  if (!s_pet.initialized || !s_pet.sprite) return;
331	
332	  s_pet.state = st;
333	
334	  /* Reset the sprite to a clean base frame; per-state anim re-derives it. */
335	  lv_image_set_src(s_pet.sprite, s_frames->base);
336	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);  /* clear any shake offset */
337	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);  /* clear any float offset */
338	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
339	
340	  if (s_pet.label) lv_label_set_text(s_pet.label, display_text_for(st));
341	  if (s_pet.status_dot) {
342	    lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(s_state_color[st]), 0);
343	    /* Legend (idle) has no status dot; busy states show it. */
344	    if (st == PET_STATE_IDLE)
345	      lv_obj_add_flag(s_pet.status_dot, LV_OBJ_FLAG_HIDDEN);
346	    else
347	      lv_obj_remove_flag(s_pet.status_dot, LV_OBJ_FLAG_HIDDEN);
348	  }
349	
350	  start_anim_for(st);
351	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
352	}
353	
354	void pet_status_view_set_state(enum pet_state state)
355	{
356	  if ((int)state < 0 || (int)state > PET_STATE_ERROR) return;
357	  /* Async: widget mutation must happen in the LVGL thread. */
358	  lv_async_call(apply_state_async_cb, (void *)(intptr_t)state);
359	}
360	
361	static void apply_type_async_cb(void *data)
362	{
363	  enum pet_type type = (enum pet_type)(intptr_t)data;
364	  if (!s_pet.initialized || !s_pet.sprite) return;
365	
366	  s_pet.type = type;
367	  s_frames = &s_frames_by_type[type];
368	
369	  /* Re-derive the current state's expression under the new sprite sheet and
370	   * restart its anim (blink_cb reads s_frames, so it picks up the swap too). */
371	  lv_image_set_src(s_pet.sprite, s_frames->base);
372	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);
373	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);
374	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
375	
376	  start_anim_for(s_pet.state);
377	  syslog(LOG_INFO, "[%s] type → %d\n", TAG, (int)type);
378	}
379	
380	void pet_status_view_set_type(int type)
381	{
382	  if (type < 0 || type >= PET_TYPE_COUNT) type = PET_TYPE_CAT;
383	  lv_async_call(apply_type_async_cb, (void *)(intptr_t)type);
384	}
385	
386	/* ---------- screen show / hide ---------- */
387	
388	static void show_async_cb(void *data)
389	{
390	  (void)data;
391	  if (!s_pet.initialized || !s_pet.screen || s_pet.visible) return;
392	  s_pet.prev_screen = lv_screen_active();
393	  lv_screen_load_anim(s_pet.screen, LV_SCR_LOAD_ANIM_FADE_IN,
394	                      SCREEN_FADE_MS, 0, false);
395	  /* lv_screen_load already invalidates the full screen and schedules a redraw;
396	   * the explicit invalidate + lv_refr_now below was a qemu-goldfish-headless
397	   * lazy-flush workaround that is unnecessary on the real CP /dev/lcd0 panel,
398	   * where it caused a full-frame (top-to-bottom) white flicker on every idle
399	   * pet↔particle rotate.  Real hardware renders screen switches fine without
400	   * the extra synchronous refresh, so we drop it to stop the standby flicker. */
401	  s_pet.visible = true;
402	  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
403	  start_anim_for(s_pet.state);
404	  syslog(LOG_INFO, "[%s] pet screen shown\n", TAG);
405	}
406	
407	void pet_status_view_show(void)
408	{
409	  if (!s_pet.initialized) return;
410	  lv_async_call(show_async_cb, NULL);
411	}
412	
413	static void hide_async_cb(void *data)
414	{
415	  (void)data;
416	  if (!s_pet.initialized || !s_pet.visible) return;
417	  stop_anim();
418	  if (s_pet.prev_screen)
419	    lv_screen_load_anim(s_pet.prev_screen, LV_SCR_LOAD_ANIM_FADE_IN,
420	                        SCREEN_FADE_MS, 0, false);
421	  s_pet.visible = false;
422	  syslog(LOG_INFO, "[%s] pet screen hidden\n", TAG);
423	}
424	
425	void pet_status_view_hide(void)
426	{
427	  if (!s_pet.initialized) return;
428	  lv_async_call(hide_async_cb, NULL);
429	}
430	
431	bool pet_status_view_is_visible(void)
432	{
433	  return s_pet.visible;
434	}
