436	/* ---------- init ---------- */
437	
438	int pet_status_view_init(void)
439	{
440	  if (s_pet.initialized) return 0;
441	
442	  memset(&s_pet, 0, sizeof(s_pet));
443	  s_pet.state = PET_STATE_IDLE;
444	  s_pet.type = PET_TYPE_CAT;
445	  s_frames = &s_frames_by_type[PET_TYPE_CAT];
446	
447	  s_pet.screen = lv_obj_create(NULL);
448	  if (!s_pet.screen) return -ENOMEM;
449	  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(UI_PAL_BG), 0);
450	  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
451	  lv_obj_set_style_text_font(s_pet.screen, &lv_font_misans_16_cjk, 0);
452	
453	  /* Ring (arc) — centered, subtle dark track, state-colored indicator. */
454	  s_pet.ring = lv_arc_create(s_pet.screen);
455	  if (s_pet.ring)
456	    {
457	      lv_obj_set_size(s_pet.ring, PET_RING_SIZE, PET_RING_SIZE);
458	      lv_obj_align(s_pet.ring, LV_ALIGN_CENTER, 0, -PET_LIFT_UP);
459	      lv_arc_set_rotation(s_pet.ring, 0);
460	      lv_arc_set_bg_angles(s_pet.ring, 0, 360);
461	      lv_arc_set_angles(s_pet.ring, 0, 360);
462	      lv_arc_set_range(s_pet.ring, 0, 360);
463	      /* Track (LV_PART_MAIN): a subtle dark full circle that stays put. */
464	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_MAIN);
465	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_TRACK), LV_PART_MAIN);
466	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_MAIN);
467	      /* Indicator (LV_PART_INDICATOR): the state-colored spinner / fill.
468	       * (Previously only LV_PART_MAIN was styled, so the animated segment fell
469	       * back to the theme's default blue arc — the "ugly" ring.) */
470	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_INDICATOR);
471	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_IDLE), LV_PART_INDICATOR);
472	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_INDICATOR);
473	      lv_obj_remove_flag(s_pet.ring, LV_OBJ_FLAG_CLICKABLE);
474	      /* Hide the arc knob. */
475	      lv_obj_set_style_bg_opa(s_pet.ring, LV_OPA_TRANSP, LV_PART_KNOB);
476	    }
477	
