  { KEY_BIT(2), GESTURE_TAP,    action_deny },
};

static const struct keyctx_s g_global_ctx =
{
  GLOBAL_MAP_NAME, g_global_map,
  sizeof(g_global_map) / sizeof(g_global_map[0]), NULL, NULL
};

