#!/usr/bin/env python3
"""BK7258 console: send a command, wait for the shell prompt, print output."""
import re
import sys
import time
import serial

DEV = "/dev/ttyUSB0"
PROMPTS = (b"nsh-ap>", b"vela>", b"nsh>")
NOISE = re.compile(rb"\[lv_nuttx_lcd\] flush[^\n]*\n|\[LVGL\] \[[^\n]*\n")


def clean(b):
    b = NOISE.sub(b"", b)
    return b.decode("utf-8", "replace")


def wait_prompt(ser, timeout):
    end = time.time() + timeout
    buf = bytearray()
    while time.time() < end:
        d = ser.read(4096)
        if d:
            buf += d
            if any(p in buf[-200:] for p in PROMPTS):
                break
    return bytes(buf)


def main():
    ser = serial.Serial(DEV, 115200, timeout=0.2)
    ser.reset_input_buffer()

    # settle
    time.sleep(0.3)
    ser.reset_input_buffer()

    cmds = sys.argv[1:]
    for cmd in cmds:
        if cmd.startswith("SLEEP:"):
            print("--- sleep %s ---" % cmd[6:], flush=True)
            end = time.time() + float(cmd[6:])
            buf = bytearray()
            while time.time() < end:
                d = ser.read(65536)
                if d:
                    buf += d
            print(clean(buf), flush=True)
            continue

        print("\n>>> " + cmd, flush=True)
        ser.write(cmd.encode() + b"\r\n")
        buf = wait_prompt(ser, 6.0)
        print(clean(buf), flush=True)
        if not any(p in buf[-200:] for p in PROMPTS):
            print("[warn] no prompt seen after %r" % cmd, flush=True)
    ser.close()


if __name__ == "__main__":
    main()

