static void* lv_loop_thread(void* arg)
{
    (void)arg;
    while (s_lv_loop_running) {
        uint32_t idle;

        /* Serialize with cross-thread lv_async_call()/lv_timer_create()
         * users.  CONFIG_LV_USE_OS=0 means LVGL does no locking itself. */
        lvgl_ui_lock();
        idle = lv_timer_handler();
        lvgl_ui_unlock();

        if (idle == 0)
            idle = 1;
        usleep(idle * 1000);
    }
    return NULL;
}

