249	/**
250	 *  Convert a design convergence tolerance expressed as an ABSOLUTE distance to
251	 *  the target (in the channel's natural property units — LV_SCALE_NONE units
252	 *  for scale, LV_OPA units for opacity) into the normalized "fraction of full
253	 *  travel" the spring engine expects. The driver runs 0..SPRING_NORM_MAX and
254	 *  setup_driver scales the returned fraction back up by SPRING_NORM_MAX, so the
255	 *  engine's |err| <= threshold*SPRING_NORM_MAX test fires exactly when the real
256	 *  property is within @p abs_tol of @p end. Degenerate zero-travel channels
257	 *  (begin == end) return a tiny non-zero fraction so the channel is treated as
258	 *  immediately converged rather than never converging.
259	 */
260	static float exit_threshold_fraction(int32_t begin, int32_t end, float abs_tol)
261	{
262	    int32_t travel = end - begin;
263	    if (travel < 0) {
264	        travel = -travel;
265	    }
266	    if (travel == 0) {
267	        return 0.0001f;
268	    }
269	    return abs_tol / (float)travel;
270	}
