272	/**
273	 * Build the shared per-channel exit springs for an app-leaving transition
274	 * (app->launcher and app->widget), configuring independent scale and opacity
275	 * spring coefficients on both the in (returning) and out (leaving) params.
276	 *
277	 * @param action    navigation action to wire in/out funcs into (may be NULL)
278	 * @param in_param   returning-side param to populate (must be non-NULL)
279	 * @param out_param  leaving-side param to populate (must be non-NULL)
280	 * @param need_init  when true, both params are lvx_anim_param_init'd first
281	 * @param scale_coef   scale channel spring coefficients
282	 *                     {damping, response, velocity, threshold}; threshold
283	 *                     domain governed by threshold_is_design_abs
284	 * @param opacity_coef opacity channel spring coefficients
285	 *                     {damping, response, velocity, threshold}; threshold
286	 *                     domain governed by threshold_is_design_abs
287	 * @param threshold_is_design_abs  when true, the coefficient thresholds are
288	 *        design-absolute convergence tolerances in each channel's natural
289	 *        property domain (scale: LV_SCALE_NONE units; opacity: LV_OPA units,
290	 *        0..255 where LV_OPA_100 == 255) and are converted to the spring
291	 *        engine's normalized "fraction of channel travel" via
292	 *        exit_threshold_fraction (the driver runs 0..SPRING_NORM_MAX and
293	 *        setup_driver multiplies the passed value by SPRING_NORM_MAX); when
294	 *        false the values pass through unchanged so the legacy single-spring
295	 *        callers stay byte-for-byte identical.
296	 */
297	static void params_app_exit_scale_common(
298	    lvx_navi_action* action, lvx_anim_param_t* in_param,
299	    lvx_anim_param_t* out_param, bool need_init,
300	    const lvx_anim_spring_coef_t* scale_coef,
301	    const lvx_anim_spring_coef_t* opacity_coef, bool threshold_is_design_abs)
302	{
303	    if (action == NULL || in_param == NULL || out_param == NULL) {
304	        return;
305	    }
306	
307	    action->in.func = lvx_anim_page_scale_spring_in;
308	    action->out.func = lvx_anim_page_scale_spring_out;
309	
310	    lv_point_t coord = { out_param->pivot.x, out_param->pivot.y };
311	    lv_point_t p = { 0, 0 };
312	
313	    if (need_init) {
314	        lvx_anim_param_init(in_param);
315	        lvx_anim_param_init(out_param);
316	    }
317	
318	    p.x = coord.x;
319	    p.y = coord.y;
320	    if (in_param->begin_scale == 0) {
321	        in_param->begin_scale = 990;
322	    }
323	    anim_debug("begin scale %" PRId32 "\n", in_param->begin_scale);
324	    in_param->end_scale = LV_SCALE_NONE;
325	    in_param->begin_alpha = LV_OPA_100;
326	    in_param->end_alpha = LV_OPA_100;
327	    in_param->pivot = p;
328	    in_param->begin_pos = -coord.x;
329	    in_param->end_pos = 0;
330	    in_param->begin_pos_y = -coord.y;
331	    in_param->end_pos_y = 0;
332	    in_param->duration = 200;
333	    in_param->delay = 0;
334	
335	    p.x = 0;
336	    p.y = 0;
337	    out_param->begin_scale = LV_SCALE_NONE;
338	    if (out_param->end_scale == 0 || out_param->end_scale > LV_SCALE_NONE) {
339	        out_param->end_scale = 66;
340	    }
341	    out_param->begin_alpha = LV_OPA_100;
342	    out_param->end_alpha = LV_OPA_0;
343	    out_param->pivot = p;
344	    out_param->begin_pos = 0;
345	    out_param->end_pos = coord.x;
346	    out_param->begin_pos_y = 0;
347	    out_param->end_pos_y = coord.y;
348	    out_param->duration = 200;
349	    out_param->delay = 0;
350	    /* Per-channel exit springs: scale and opacity carry independent
351	     * coefficient sets. POS_X/POS_Y are left DEFAULT so position follows the
352	     * scale channel (single-gesture geometry preserved).
353	     *
354	     * The spring engine's convergence test runs in the NORMALIZED driver domain
355	     * (0..SPRING_NORM_MAX): setup_driver feeds it threshold*SPRING_NORM_MAX, so
356	     * the threshold is interpreted as "fraction of the channel's full travel
357	     * still remaining to the target". A design tolerance expressed as an
358	     * ABSOLUTE distance to the target (scale: LV_SCALE_NONE units; opacity:
359	     * LV_OPA units) must therefore be divided by that channel's actual travel
360	     * |end-begin|, separately for the in (returning launcher) and out (leaving
361	     * app) params since their travels differ.
362	     *
363	     * In an engine-off build there is no spring engine to drive these channels;
364	     * the scheduler's timing resolver degrades a CURVE_SPRING channel to the
365	     * legacy spring-bezier curve, so setting the coefficients here is safe and
366	     * needs no CONFIG_ANIMATION_ENGINE guard. */
367	    float s_thr_in = scale_coef->threshold;
368	    float s_thr_out = scale_coef->threshold;
369	    float o_thr_in = opacity_coef->threshold;
370	    float o_thr_out = opacity_coef->threshold;
371	    if (threshold_is_design_abs) {
372	        s_thr_in = exit_threshold_fraction(
373	            in_param->begin_scale, in_param->end_scale, scale_coef->threshold);
374	        s_thr_out = exit_threshold_fraction(out_param->begin_scale,
375	                                            out_param->end_scale,
376	                                            scale_coef->threshold);
377	        o_thr_in = exit_threshold_fraction(in_param->begin_alpha,
378	                                           in_param->end_alpha,
379	                                           opacity_coef->threshold);
380	        o_thr_out = exit_threshold_fraction(out_param->begin_alpha,
381	                                            out_param->end_alpha,
382	                                            opacity_coef->threshold);
383	    }
384	    lvx_anim_param_set_channel_spring(in_param, LVX_ANIM_CH_SCALE, 200,
385	                                      scale_coef->damping, scale_coef->response,
386	                                      scale_coef->velocity, s_thr_in);
387	    lvx_anim_param_set_channel_spring(out_param, LVX_ANIM_CH_SCALE, 200,
388	                                      scale_coef->damping, scale_coef->response,
389	                                      scale_coef->velocity, s_thr_out);
390	    lvx_anim_param_set_channel_spring(
391	        in_param, LVX_ANIM_CH_OPACITY, 200, opacity_coef->damping,
392	        opacity_coef->response, opacity_coef->velocity, o_thr_in);
393	    lvx_anim_param_set_channel_spring(
394	        out_param, LVX_ANIM_CH_OPACITY, 200, opacity_coef->damping,
395	        opacity_coef->response, opacity_coef->velocity, o_thr_out);
396	}
