996	static void apply_screen_state_change(screen_state_t previous_state,
997	                                      screen_state_t current_state,
998	                                      screen_state_change_source_t source)
999	{
1000	    if (previous_state == current_state) {
1001	        return;
1002	    }
1003	    screen_set_state(current_state);
1004	
1005	    if (g_screen.state_change.is_applying) {
1006	        g_screen.state_change.has_pending = true;
1007	        g_screen.state_change.pending_state = current_state;
1008	        g_screen.state_change.pending_souce = source;
1009	        MIWEAR_INFO(
1010	            MiWearScreen,
1011	            "is applying screen state: %s. pend the change, screen state:%s, "
1012	            "change source:%s\n",
1013	            screen_state_name[g_screen.state_change.current_state],
1014	            screen_state_name[g_screen.state_change.pending_state],
1015	            screen_change_source_name[g_screen.state_change.pending_souce]);
1016	        return;
1017	    }
1018	
1019	    g_screen.state_change.is_applying = true;
1020	    g_screen.state_change.previous_state = previous_state;
1021	    g_screen.state_change.current_state = current_state;
1022	    g_screen.state_change.source = source;
1023	
1024	    uv_async_send(&g_screen.state_change.applying_async);
1025	}
