1050	static void relax_normal(const char* tag, _screen_state_t next_state)
1051	{
1052	    screen_state_t previous_state = screen_get_state();
1053	    if (g_screen.normal_stay_count > 0) {
1054	        g_screen.normal_stay_count--;
1055	    }
1056	    MIWEAR_INFO(MiWearScreen, "tag:%s, normal_stay_count:%d\n", tag,
1057	                g_screen.normal_stay_count);
1058	
1059	    if (g_screen.normal_stay_count == 0) {
1060	        /**
1061	         *  Need to set current state here because the state has already been
1062	         *  changed.
1063	         */
1064	        screen_set_state(state_convert(next_state));
1065	
1066	        bool has_auto_stop = false;
1067	        screen_session_t* session = NULL;
1068	        screen_session_t* temp_session = NULL;
1069	        list_for_every_entry_safe(&g_screen.started_session_queue, session,
1070	                                  temp_session, screen_session_t, node)
1071	        {
1072	            if (session->auto_stop) {
1073	                list_delete(&session->node);
1074	                session->started = false;
1075	                list_add_tail(&g_screen.idle_session_list, &session->node);
1076	                has_auto_stop = true;
1077	            }
1078	        }
1079	
1080	        if (has_auto_stop) {
1081	            apply_session_settings();
1082	        }
1083	
1084	        apply_screen_state_change(previous_state, screen_get_state(),
1085	                                  g_screen.screen_state_change_source);
1086	    }
1087	}
