406	/**
407	 * @brief Enter AOD mode for a specific activity
408	 * @param current The activity page to enter AOD mode for
409	 */
410	static void enter_aod_activity(lvx_page_t* current)
411	{
412	    if (!current) {
413	        warn("No AOD-capable activity available, skipping AOD enter\n");
414	        return;
415	    }
416	    const char* page_name = current->uri ? current->uri : "unknown";
417	    info("Entering AOD mode for {0x%" PRIX16 ", 0x%" PRIX16 "} page: %s\n",
418	         current->app_id, current->page_id, page_name);
419	
420	    /* Step 1: Get system AOD root container */
421	    lv_obj_t* root = lvx_system_ui_get_aod_root();
422	    if (!root) {
423	        err("Failed to get AOD root for page '%s'\n", page_name);
424	        return;
425	    }
426	
427	    /* Step 2: Create AOD content wrapper using on_aod_ui_create */
428	    on_aod_ui_create(current, root);
429	    if (!current->aod_content) {
430	        err("Failed to create AOD content for page '%s'\n", page_name);
431	        /* Don't release AOD root here - it will be released when exiting AOD
432	         * mode */
433	        return;
434	    }
435	
436	    /* Step 3: Call application's AOD enter callback */
437	    if (!current->on_aod_create) {
438	        err("Page '%s' has NULL on_aod_create callback\n", page_name);
439	        lv_obj_del(current->aod_content);
440	        current->aod_content = NULL;
441	        /* Don't release AOD root here - it will be released when exiting AOD
442	         * mode */
443	        return;
444	    }
445	
446	    current->on_aod_create(current, current->aod_content);
447	
448	    /* Step 4: Update AOD manager state */
449	    current->in_aod_mode = true;
450	    g_aod_ctx.state = AOD_STATE_ACTIVE;
451	    g_aod_ctx.current_page = current;
452	    g_aod_ctx.is_default_aod = current == activitymanager_get_home_page();
453	    g_aod_ctx.refresh_count = 0;
454	    g_aod_ctx.enter_time_ms = get_realtime_ms();
455	
456	    /* Step 5: Set custom AOD refresh interval if specified by the page */
457	    if (current->aod_refresh_interval > 0) {
458	        screen_set_aod_refresh_interval(current->aod_refresh_interval);
459	    }
460	
461	    info("Entering AOD mode successfully for {0x%" PRIX16 ", 0x%" PRIX16
462	         "} page: %s (refresh interval: %" PRIu32 " s)\n",
463	         current->app_id, current->page_id, page_name,
464	         current->aod_refresh_interval / 1000);
465	}
