467	/**
468	 * @brief Exit AOD mode for a specific activity
469	 * @param current The activity page to exit AOD mode for
470	 */
471	static void exit_aod_activity(lvx_page_t* current)
472	{
473	    if (!current || !current->aod_content) {
474	        err("Error: Invalid page or AOD content\n");
475	        return;
476	    }
477	
478	    const char* page_name = current->uri ? current->uri : "unknown";
479	
480	    info("Exiting AOD mode for page %s\n", page_name);
481	
482	    /* Step 1: Call application's AOD exit callback */
483	    if (current->on_aod_destroy) {
484	        current->on_aod_destroy(current, current->aod_content);
485	    }
486	
487	    /* Step 2: Release system AOD root container */
488	    lvx_system_ui_release_aod_root();
489	
490	    /* Step 3: Clean page AOD content */
491	    if (current->aod_content) {
492	        lv_obj_del(current->aod_content);
493	        current->aod_content = NULL;
494	    }
495	
496	    /* Step 4: Update page state */
497	    current->in_aod_mode = false;
498	
499	    /* Step 5: Reset custom AOD refresh interval to default (0) */
500	    screen_set_aod_refresh_interval(0);
501	
502	    info("AOD mode exited for page '%s', refresh count: %lu\n", page_name,
503	         (unsigned long)g_aod_ctx.refresh_count);
504	}
