506	/**
507	 * @brief Switch AOD from old page to new page
508	 * @param old_page The old page that was in AOD mode
509	 * @param new_page The new page to switch to AOD mode
510	 */
511	static void switch_aod(lvx_page_t* old_page, lvx_page_t* new_page)
512	{
513	    /* Step 1: Exit AOD mode for old page */
514	    exit_aod_activity(old_page);
515	
516	    /* Step 2: Enter AOD mode for new page */
517	    enter_aod_activity(new_page);
518	
519	    /* Step 3: Update AOD context */
520	    lvx_eventbus_send(LVX_EVENT_AOD_REFRESHING, NULL, false);
521	}
