526	 */
527	static void enter_aod(void)
528	{
529	    /* Validate state transition */
530	    if (g_aod_ctx.state == AOD_STATE_ACTIVE) {
531	        debug("Already in AOD mode, skipping\n");
532	        return;
533	    }
534	
535	    if (g_aod_ctx.state == AOD_STATE_REFRESHING) {
536	        warn("Cannot enter AOD while refreshing, skipping\n");
537	        return;
538	    }
539	
540	    enter_aod_activity(get_aod_activity());
