543	/**
544	 * @brief Exit AOD mode
545	 * @note Called when screen state changes to ON or when page is popped
546	 */
547	static void exit_aod(void)
548	{
549	    if (g_aod_ctx.state != AOD_STATE_ACTIVE) {
550	        debug("Not in AOD mode, skipping\n");
551	        return;
552	    }
553	
554	    lvx_page_t* current = g_aod_ctx.current_page;
555	    exit_aod_activity(current);
556	
557	    /* 5. If it's default AOD (Home), don't clear page reference */
558	    if (g_aod_ctx.is_default_aod) {
559	        cleanup_aod_state();
560	    } else {
561	        g_aod_ctx.state = AOD_STATE_IDLE;
