567	 * @note Called by Screen Manager's AOD refresh timer (every 60 seconds)
568	 */
569	/**
570	 * @brief AOD refresh callback
571	 * @note Called by Screen Manager's AOD refresh timer (every 60 seconds)
572	 */
573	static void on_aod_refresh(void)
574	{
575	    /* Step 1: Validate state */
576	    if (g_aod_ctx.state != AOD_STATE_ACTIVE) {
577	        debug("Not in AOD mode, skipping refresh\n");
578	        return;
579	    }
580	
581	    lvx_page_t* page = g_aod_ctx.current_page;
582	    if (!page || !page->in_aod_mode) {
583	        debug("Invalid page state\n");
584	        return;
585	    }
586	
587	    /* Step 2: Update state to refreshing */
588	    g_aod_ctx.state = AOD_STATE_REFRESHING;
589	
590	    /* Step 3: Check AOD content state */
591	    bool content_is_hidden
592	        = lv_obj_has_flag(page->aod_content, LV_OBJ_FLAG_HIDDEN);
593	    info("AOD content %p hidden: %s\n", page->aod_content,
594	         content_is_hidden ? "YES" : "NO");
595	
596	    /* Step 4: Call application's refresh callback */
597	    if (page->on_aod_refresh) {
598	        page->on_aod_refresh(page, page->aod_content);
599	    }
600	
601	    /* Step 5: Update statistics */
602	    update_performance_stats(page);
603	
604	    /* Step 6: Restore state to active */
605	    g_aod_ctx.state = AOD_STATE_ACTIVE;
606	}
