80	static void refresh_time(void)
81	{
82	  if (!s_sb.initialized) return;
83	
84	  time_t now = time(NULL);
85	  struct tm tm;
86	  localtime_r(&now, &tm);
87	
88	  if (s_sb.clock)
89	    {
90	      char buf[16];
91	      snprintf(buf, sizeof(buf), "%02d:%02d", tm.tm_hour, tm.tm_min);
92	      lv_label_set_text(s_sb.clock, buf);
93	    }
94	  if (s_sb.date)
95	    {
96	      char buf[32];
97	      snprintf(buf, sizeof(buf), "%d月%d日 %s",
98	               tm.tm_mon + 1, tm.tm_mday, s_wday_cn[tm.tm_wday % 7]);
99	      lv_label_set_text(s_sb.date, buf);
100	    }
101	}
