112	static void show_async_cb(void *data)
113	{
114	  (void)data;
115	  if (!s_sb.initialized || !s_sb.screen || s_sb.visible) return;
116	  s_sb.prev_screen = lv_screen_active();
117	  refresh_time();
118	
119	  /* 背景与上一屏同为不透明 UI_PAL_BG,直接换屏瞬时可见性无差;只对内容层做
120	   * opacity 淡入(脏区 = 内容包围盒,而非整屏),淡入不再受整帧 SPI flush 限制。
121	   * 先手动把内容层压到全透明,避免换屏后首帧闪一下。 */
122	  if (s_sb.content)
123	    {
124	      lv_obj_set_style_opa(s_sb.content, LV_OPA_TRANSP, 0);
125	      lv_screen_load(s_sb.screen);
126	      lv_obj_fade_in(s_sb.content, SCREEN_FADE_MS, 0);
127	    }
128	  else
129	    {
130	      lv_screen_load(s_sb.screen);
131	    }
132	
133	  s_sb.visible = true;
134	  syslog(LOG_INFO, "[%s] standby clock shown\n", TAG);
135	}
