3271	void screen_turn_state(const char* const tag, screen_state_t state,
3272	                       miwear_active_event_t event)
3273	{
3274	    switch (state) {
3275	    case SCREEN_STATE_ON:
3276	        screen_turn_on(tag, event);
3277	        break;
3278	    case SCREEN_STATE_OFF:
3279	        turn_off(tag, SCREEN_STATE_OFF);
3280	        break;
3281	    case SCREEN_STATE_IDLE:
3282	        turn_off(tag, SCREEN_STATE_IDLE);
3283	        break;
3284	    case SCREEN_STATE_UNCONTROLLED:
3285	        screen_remove_control(tag);
3286	        break;
3287	    default:
3288	        warn("unknown state(%d), ignore\n", state);
3289	        break;

    }

    if (!screen_is_on()) {
        goto exit;
    }

    g_screen.dimmer_timeout_uptime
        += (effective_dimmer_timeout
            - applied_settings->dimmer_timeout_milliseconds);

    int64_t current_uptime = get_uptime_ms();
    int64_t max_timeout_uptime = current_uptime + effective_dimmer_timeout;
    if (g_screen.dimmer_timeout_uptime > max_timeout_uptime) {
        g_screen.dimmer_timeout_uptime = max_timeout_uptime;
    }

    if (uv_is_active((uv_handle_t*)&g_screen.dimmer_timer)) {
        if (effective_dimmer_timeout
            > applied_settings->dimmer_timeout_milliseconds) {
            goto exit;
        }

        uv_timer_stop(&g_screen.dimmer_timer);
        if (g_screen.dimmer_timeout_uptime <= current_uptime) {
            uv_update_time(g_screen.loop);
            uv_timer_start(&g_screen.dimmer_timer, dimmer_timer_cb, 0, 0);
        } else {
            uv_update_time(g_screen.loop);
            uv_timer_start(&g_screen.dimmer_timer, dimmer_timer_cb,
                           g_screen.dimmer_timeout_uptime - current_uptime, 0);
        }
    } else {
        if (effective_dimmer_timeout
            < applied_settings->dimmer_timeout_milliseconds) {
            goto exit;
        }

        if (g_screen.dimmer_timeout_uptime > current_uptime) {
            stay_normal("dimmer_timer");
            uv_update_time(g_screen.loop);
            uv_timer_start(&g_screen.dimmer_timer, dimmer_timer_cb,
                           g_screen.dimmer_timeout_uptime - current_uptime, 0);
        }
    }

exit:
    applied_settings->dimmer_timeout_milliseconds = effective_dimmer_timeout;

    MIWEAR_INFO(MiWearScreen, "dimmer_timeout_milliseconds:%d\n",
                applied_settings->dimmer_timeout_milliseconds);
}

