372	/* Idle-yield support: when the pet status ring is enabled, the chat screen
373	 * yields the foreground to the pet after PET_IDLE_YIELD_MS of message silence.
374	 * All access is confined to the LVGL thread (init creates the timer; the send
375	 * async cb resets the tick; the timer cb does the yield). */
376	static lv_timer_t *s_pet_idle_timer = NULL;
377	static uint32_t    s_pet_last_msg_tick = 0;
378	
379	static void pet_idle_timer_cb(lv_timer_t *t)
380	{
381	    (void)t;
382	    if (!s_state.initialized || !s_state.screen_visible) return;
383	    /* A pending remote permission request owns the foreground: never yield it
384	     * back to the pet home screen while the approval page is up, or the user
385	     * loses the S2/S3 approve/cancel cue mid-decision. */
386	    if (s_state.approval_visible) return;
387	    /* Judge by the active screen, not the cached visible flag: opening the
388	     * chat screen does not call pet_status_view_hide(), so the flag stays true
389	     * and the yield below would never fire (blank chat page stuck forever). */
390	    if (!pet_status_view_is_active() &&
391	        (lv_tick_get() - s_pet_last_msg_tick) >= PET_IDLE_YIELD_MS)
392	      {
