1	/****************************************************************************
2	 * chips/bk7258/wlan_ctrl/wlan_ctrl_cli.c
3	 *
4	 * NSH front end for the cross-core Wi-Fi control plane, named `wapi` and
5	 * taking the same arguments as the NuttX wapi tool on CP so that switching
6	 * consoles does not mean switching habits:
7	 *
8	 *   wapi scan [ifname]                  scan and print the list
9	 *   wapi scan_results [ifname]          print the last list again
10	 *   wapi psk <ifname> <pass> [alg]      set the passphrase
11	 *   wapi essid <ifname> <ssid> [flag]   set the ssid; flag 1 connects
12	 *   wapi connect <ssid> <pass>          both of the above in one go
13	 *   wapi disconnect [ifname]            drop the link
14	 *
15	 * The ifname is accepted and ignored: the only station is wlan0 and it
16	 * lives on CP.  This is the rpmsg face; CP's own `wapi` is the wext face
17	 * of the same operations (compat/bk7258_armino_wops.c), and both end up
18	 * in chips/bk7258/wlan_ctrl/wlan_ctrl_server.c, so they share one job
19	 * queue and cannot race into the Armino connect twice.
20	 *
21	 * The password is never printed.
22	 ****************************************************************************/
23	
24	#include <errno.h>
25	#include <stdio.h>
26	#include <stdlib.h>
27	#include <string.h>
28	#include <unistd.h>
