35	static void wifi_showusage(FAR const char *progname)
36	{
37	  printf("Usage:\n");
38	  printf("  %s scan [ifname]\n", progname);
39	  printf("  %s scan_results [ifname]\n", progname);
40	  printf("  %s psk <ifname> <passphrase> [alg]\n", progname);
41	  printf("  %s essid <ifname> <ssid> [flag]\n", progname);
42	  printf("  %s connect <ssid> <passphrase>\n", progname);
43	  printf("  %s disconnect [ifname]\n", progname);
44	  printf("\n");
45	  printf("  essid flag: 0 off, 1 on (connects), 2 delayed\n");
46	  printf("  psk alg:    0 none, 1 wep, 2 tkip, 3 ccmp\n");
47	}
