49	static int do_scan(void)
50	{
51	  struct wifi_ap_info_s aps[32];
52	  int n = 0;
53	  int ret;
54	  int i;
55	
56	  ret = wifi_ctrl_scan_start();
57	  if (ret < 0)
58	    {
59	      printf("scan start failed: %d\n", ret);
60	      return 1;
61	    }
62	
63	  /* Armino's scan is asynchronous; poll until results show up. */
64	
65	  for (i = 0; i < 50; i++)
66	    {
67	      ret = wifi_ctrl_scan_get(aps, 32, &n);
68	      if (ret < 0)
69	        {
70	          printf("scan get failed: %d\n", ret);
71	          return 1;
72	        }
73	
74	      if (n > 0)
75	        {
76	          break;
77	        }
78	
79	      usleep(100 * 1000);
80	    }
81	
82	  printf("bssid                ch  rssi  sec  ssid\n");
83	  for (i = 0; i < n; i++)
84	    {
85	      printf("%02x:%02x:%02x:%02x:%02x:%02x  %3d  %4d  %3s  %s\n",
86	             aps[i].bssid[0], aps[i].bssid[1], aps[i].bssid[2],
87	             aps[i].bssid[3], aps[i].bssid[4], aps[i].bssid[5],
88	             aps[i].channel, aps[i].rssi,
89	             aps[i].secured ? "yes" : "no", aps[i].ssid);
90	    }
91	
92	  if (n == 0)
93	    {
94	      printf("(no APs)\n");
95	    }
96	
97	  return 0;
98	}
