100	static int do_connect(FAR const char *ssid, FAR const char *pass)
101	{
102	  int ret = wifi_ctrl_connect(ssid, pass);
103	
104	  if (ret < 0)
105	    {
106	      printf("connect failed: %d\n", ret);
107	      return 1;
108	    }
109	
110	  printf("connecting to %s\n", ssid);
111	  return 0;
112	}
