114	/* wapi psk / wapi essid arrive as two separate commands; hold the halves
115	 * between them and connect when essid's flag is 1, which is what
116	 * netdev_upper_wireless_ioctl() does on the wext face.
117	 */
118	
119	int main(int argc, FAR char *argv[])
120	{
121	  if (argc < 2)
122	    {
123	      wifi_showusage(argv[0]);
124	      return EXIT_FAILURE;
125	    }
126	
127	  if (strcmp(argv[1], "scan") == 0 || strcmp(argv[1], "scan_results") == 0)
128	    {
129	      return do_scan();
130	    }
131	
132	  if (strcmp(argv[1], "psk") == 0)
133	    {
134	      FAR const char *pass = (argc >= 4) ? argv[3] : (argc >= 3 ? argv[2] : NULL);
135	
136	      if (pass == NULL)
137	        {
138	          wifi_showusage(argv[0]);
139	          return EXIT_FAILURE;
140	        }
141	
142	      strlcpy(s_pass, pass, sizeof(s_pass));
143	      return 0;
144	    }
145	
146	  if (strcmp(argv[1], "essid") == 0)
147	    {
148	      FAR const char *ssid = (argc >= 4) ? argv[3] : (argc >= 3 ? argv[2] : NULL);
149	      int flag = (argc >= 5) ? atoi(argv[4]) : 1;
150	
151	      if (ssid == NULL)
152	        {
153	          wifi_showusage(argv[0]);
154	          return EXIT_FAILURE;
155	        }
156	
157	      strlcpy(s_ssid, ssid, sizeof(s_ssid));
158	      if (flag == 1)
159	        {
160	          return do_connect(s_ssid, s_pass);
161	        }
162	
163	      return 0;
164	    }
165	
166	  if (strcmp(argv[1], "connect") == 0)
167	    {
168	      if (argc < 4)
169	        {
170	          wifi_showusage(argv[0]);
171	          return EXIT_FAILURE;
172	        }
173	
174	      strlcpy(s_ssid, argv[2], sizeof(s_ssid));
175	      strlcpy(s_pass, argv[3], sizeof(s_pass));
176	      return do_connect(s_ssid, s_pass);
177	    }
178	
179	  if (strcmp(argv[1], "disconnect") == 0)
180	    {
181	      int ret = wifi_ctrl_disconnect();
182	
183	      if (ret < 0)
184	        {
185	          printf("disconnect failed: %d\n", ret);
186	          return 1;
187	        }
188	
